<?php use SwimlogStandalone\PlanEvaluation as PE;use SwimlogStandalone\SwimComparison as SC;use SwimLogEvaluation\Workout;require_once __DIR__.'/SwimComparison.php';$distance=static function($v){return $v===null?'Unknown':number_format_i18n($v,2).' m';};$delta=static function($a,$b,$time=false){if($a===null||$b===null)return 'Unavailable';$d=$b-$a;return ($d>0?'+':($d<0?'−':'')).($time?Workout::format_duration(abs($d)):number_format_i18n(abs($d),2).' m');}; ?>
<section class="calendar-panel workout-page" aria-labelledby="plan-evaluation-title"><h2 id="plan-evaluation-title">Planned versus Completed</h2><p>Compare an explicitly matched swimming plan and recorded swim. This read-only report never matches automatically or changes the plan, prescription, record or history locks. Positive differences mean more distance or more elapsed time, not a better or worse workout.</p>
<?php if(is_wp_error($planEvaluation)): ?><p role="alert"><?php echo esc_html($planEvaluation->get_error_message()); ?></p><?php else:$m=$planEvaluation; ?>
<?php if(!$m['choices']): ?><p>No swimming plans are available.</p><?php else: ?><form method="get" class="log-filters"><input type="hidden" name="screen" value="plan_evaluation"><input type="hidden" name="evaluation_page" value="<?php echo esc_attr($m['page']); ?>"><div><label for="eval-plan">Swimming plan</label><select id="eval-plan" name="evaluation_plan"><?php foreach($m['choices']as$c): ?><option value="<?php echo esc_attr($c['id']); ?>" <?php selected($m['plan']['id']??0,$c['id']); ?>><?php echo esc_html($c['date'].' · '.$c['title'].($c['matched']?' · Matched':' · Unmatched')); ?></option><?php endforeach; ?></select></div><button>Evaluate match</button></form>
<nav class="plan-actions" aria-label="Plan evaluation pages"><?php foreach(array(-1=>'Previous plans',1=>'Next plans')as$offset=>$label):$page=$m['page']+$offset;if($page<1||$page>$m['pages'])continue; ?><a class="control" href="<?php echo esc_url('/?screen=plan_evaluation&evaluation_page='.$page); ?>"><?php echo esc_html($label); ?></a><?php endforeach; ?></nav>
<?php if($m['plan']):$p=$m['plan'];$a=$m['actual'];$s=$m['structure']; ?><h3><?php echo esc_html($p['title']); ?></h3><p><?php echo esc_html('Planned: '.$p['date'].' · '.$p['status']); ?></p><div class="plan-actions"><a class="control" href="<?php echo esc_url('/?plan='.$p['id']); ?>">View planned workout</a><?php if($a): ?><a class="control" href="<?php echo esc_url('/?workout='.$a['id']); ?>">View recorded swim</a><?php endif;if($s): ?><a class="control" href="<?php echo esc_url('/?screen=structures&structure='.$s['id']); ?>">View linked prescription</a><?php endif; ?></div>
<?php if(!$a): ?><p>No recorded swim is matched. Match a workout from the planned workout details to enable comparison.</p><?php else: ?><p><?php echo esc_html('Recorded: '.$a['date']); ?></p><?php foreach($m['warnings']as$warning): ?><p class="comparison-warning"><?php echo esc_html($warning); ?></p><?php endforeach; ?>
<div class="entry-compare"><table><caption>Explicit plan targets versus recorded workout totals</caption><thead><tr><th scope="col">Metric</th><th scope="col">Planned</th><th scope="col">Recorded</th><th scope="col">Recorded − planned</th></tr></thead><tbody><tr><th scope="row">Distance</th><td><?php echo esc_html($distance($p['distance'])); ?></td><td><?php echo esc_html($distance($a['distance'])); ?></td><td><?php echo esc_html($delta($p['distance'],$a['distance'])); ?></td></tr><tr><th scope="row">Duration / elapsed time (may include rest)</th><td><?php echo esc_html(Workout::format_duration($p['duration'])); ?></td><td><?php echo esc_html(Workout::format_duration($a['elapsed'])); ?></td><td><?php echo esc_html($delta($p['duration'],$a['elapsed'],true)); ?></td></tr></tbody></table></div>
<p>Recorded moving time: <?php echo esc_html(Workout::format_duration($a['moving'])); ?>. A planned duration may include rest; it is not silently compared with moving time or used as a repetition target.</p>
<?php if($p['distance']!==null&&$a['distance']!==null):echo SC::chart($p['distance'],$a['distance'],'distance','Distance in meters: A planned, B recorded; exact values above');endif; ?>
<?php if($s): ?><h3>Linked structured prescription</h3><p><?php echo esc_html('Prescription total: '.$distance($s['distance']).' · '.$s['steps'].' expanded swim steps'); ?></p><p><?php echo esc_html($a['repetitions']===null?$a['lap_count'].' positive-distance recorded laps (not verified prescription repetitions)':$a['repetitions'].' documented manual repetitions'); ?></p><p>Step, repetition and lap counts are different kinds of evidence. This report does not infer one-to-one alignment, completion percentages, drill/equipment compliance or achieved pace targets from those counts. The current linked prescription is shown; no new historical snapshot is created.</p>
<?php if($m['strokes']): ?><div class="entry-compare"><table><caption>Structured stroke targets versus recorded active-length evidence, in meters</caption><thead><tr><th scope="col">Stroke</th><th scope="col">Prescribed</th><th scope="col">Recorded active distance</th><th scope="col">Difference</th></tr></thead><tbody><?php foreach($m['strokes']as$row): ?><tr><th scope="row"><?php echo esc_html($row['stroke']); ?></th><td><?php echo esc_html($distance($row['planned'])); ?></td><td><?php echo esc_html($distance($row['actual'])); ?></td><td><?php echo esc_html($delta($row['planned'],$row['actual'])); ?></td></tr><?php endforeach; ?></tbody></table></div><?php foreach($m['strokes']as$row)if($row['planned']!==null&&$row['actual']!==null)echo SC::chart($row['planned'],$row['actual'],'distance',$row['stroke'].' meters: A prescribed, B recorded active lengths');endif; ?>
<?php else: ?><p>This plan has no linked structured prescription. Free-text instructions are not parsed into guessed stroke distances, repetitions or timing targets.</p><?php endif; ?>
<p>Stroke evidence may be incomplete or absent, especially for open-water or summary-only records. Zero recorded distance for a stroke means no qualifying active lengths of that stroke were found; it does not prove that stroke was omitted.</p>
<?php endif;endif;endif;endif; ?></section>
